//! The committed two-bibliography fixture (T4.42), read through PDFium.
//!
//! `tests/fixtures/multi-bibliography.pdf` is generated by `scripts/make-fixtures.py`: a main
//! text, a main bibliography, an appendix, the appendix's own bibliography, and a closing note.
//! Both lists are numbered from 1, so `[3]` means *two different works* depending on which list
//! a citation belongs to. Before T4.42 the reader resolved every citation against one list, so
//! the appendix's `[3]` opened the main list's third entry — wrong in a way that looks right,
//! because the number exists and resolves.
//!
//! The test pins both directions on the real PDF: the body's `[3]` lands on the main entry and
//! the appendix's `[3]` on the appendix entry, and the CLI report names the list and the reason.
//! It skips with a printed reason when PDFium is absent (the Linux CI runner has no library).

use lyra_reader_core::{DocumentBackend, PageIndex, RawTextPage};
use lyra_reader_pdfium::PdfiumBackend;
use lyra_reader_text::{
    AttributionReason, attribute_citation, find_reference_lists, find_references, resolve_reference,
};

mod common;

fn open_fixture() -> Option<Vec<(u32, RawTextPage)>> {
    if !lyra_reader_pdfium::is_available() {
        eprintln!("skipping: no PDFium");
        return None;
    }
    let backend = PdfiumBackend::open(&common::fixture("multi-bibliography.pdf"), None)
        .expect("open the multi-bibliography fixture");
    Some(
        (0..backend.page_count())
            .map(|page| {
                let text = backend
                    .raw_text_page(PageIndex(page))
                    .expect("extract the fixture page");
                (page, text)
            })
            .collect(),
    )
}

fn hit<'a>(
    bibliography: &'a lyra_reader_text::Bibliography,
    list: usize,
    label: &str,
) -> &'a lyra_reader_text::ReferenceEntry {
    resolve_reference(&[label.to_string()], &bibliography.lists[list].entries)
        .unwrap_or_else(|| panic!("[{label}] in list {list}"))
}

#[test]
fn the_same_bracket_number_resolves_into_the_list_its_section_cites() {
    let Some(pages) = open_fixture() else {
        return;
    };
    let bibliography = find_reference_lists(pages.iter().map(|(page, text)| (*page, text)), 100);
    assert_eq!(
        bibliography.lists.len(),
        2,
        "the fixture prints two reference lists: {bibliography:?}"
    );
    assert_eq!(bibliography.document_wide, 0);
    assert_eq!(
        bibliography.lists[bibliography.document_wide].entries,
        find_references(pages.iter().map(|(page, text)| (*page, text)), 100),
        "the document-wide list must stay exactly find_references"
    );
    assert_eq!(bibliography.lists[0].first_page(), Some(1));
    assert_eq!(bibliography.lists[1].first_page(), Some(3));
    assert_eq!(bibliography.lists[1].region_start, Some(2));

    // The body citation: the main list's entry.
    let body = attribute_citation(&bibliography, 0, &["3".to_string()]).expect("bibliography");
    assert_eq!(body.list, 0, "{body:?}");
    assert_eq!(body.reason, AttributionReason::DocumentWide);
    assert!(
        hit(&bibliography, body.list, "3")
            .text
            .contains("Report work three")
    );

    // The appendix citation: the appendix list's entry. Resolving it against the document-wide
    // list is the old, silently wrong answer, and this assertion makes the difference explicit.
    let appendix = attribute_citation(&bibliography, 2, &["3".to_string()]).expect("bibliography");
    assert_eq!(appendix.list, 1, "{appendix:?}");
    assert_eq!(appendix.reason, AttributionReason::SectionList);
    let now = hit(&bibliography, appendix.list, "3");
    assert!(now.text.contains("Card work three"), "{now:?}");
    let before = hit(&bibliography, bibliography.document_wide, "3");
    assert!(before.text.contains("Report work three"), "{before:?}");
    assert_ne!(
        before.text, now.text,
        "the same number must name two different works, or the fixture proves nothing"
    );

    // A number only the appendix list prints resolves there, and the citation is not reported as
    // a main-list match.
    let only_appendix =
        attribute_citation(&bibliography, 0, &["7".to_string()]).expect("bibliography");
    assert_eq!(only_appendix.list, 1, "{only_appendix:?}");
    assert_eq!(only_appendix.reason, AttributionReason::LabelOnly);
    assert!(
        hit(&bibliography, only_appendix.list, "7")
            .text
            .contains("Card work seven")
    );

    // After both lists, proximity alone does not choose: the document-wide list wins and the
    // ambiguity is recorded.
    let closing = attribute_citation(&bibliography, 4, &["3".to_string()]).expect("bibliography");
    assert_eq!(closing.list, 0, "{closing:?}");
    assert!(closing.ambiguous, "{closing:?}");
    assert_eq!(closing.alternatives, [1]);
}

#[test]
fn the_cite_report_names_the_list_and_the_reason() {
    if !lyra_reader_pdfium::is_available() {
        eprintln!("skipping: no PDFium");
        return;
    }
    let output = std::process::Command::new(env!("CARGO_BIN_EXE_lyra-reader-cli"))
        .arg("cite")
        .arg(common::fixture("multi-bibliography.pdf"))
        .args(["--body-pages", "5", "--show-attribution", "--no-landings"])
        .output()
        .expect("run the cite report");
    assert!(
        output.status.success(),
        "cite failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let stdout = String::from_utf8_lossy(&output.stdout);
    for needle in [
        "reference lists: 2 (document-wide: list 1)",
        "list 2: pages 4..4, 8 entries, heading \"References\" p4",
        "the citation lies in the section this list closes, and the list carries its label",
        "this number exists only in the appendix list",
        "AMBIGUOUS: list 2 also carries this label",
    ] {
        assert!(
            stdout.contains(needle),
            "the cite report does not say {needle:?}:\n{stdout}"
        );
    }
    // The resolved entries, page by page: the body's [3] is the main list's, the appendix's [3]
    // is the appendix list's. Both lines carry their attribution, which is what makes the
    // behaviour inspectable without the GUI.
    assert!(
        stdout.contains("p1 [3] → [3] Three 2021. Report work three."),
        "{stdout}"
    );
    assert!(
        stdout.contains("p3 [3] → [3] Gamma 2017. Card work three."),
        "{stdout}"
    );
    assert!(
        !stdout.contains("p3 [3] → [3] Three 2021. Report work three."),
        "the appendix citation resolved into the main list:\n{stdout}"
    );
}
